   172  std::vector<EntityDefinitionClassInfo> filterRedundantClasses(
   173    ParserStatus& status, const std::vector<EntityDefinitionClassInfo>& classInfos)
   174  {
   175    auto result = std::vector<EntityDefinitionClassInfo>{};
   176    result.reserve(classInfos.size());
   177  
   178    const auto getMask = [](const auto type) { return 1 << static_cast<int>(type); };
   179  
   180    const auto baseClassMask = getMask(EntityDefinitionClassType::BaseClass);
   181  
   182    auto seen = std::unordered_map<std::string, int>{};
   183    for (const auto& classInfo : classInfos)
   184    {
   185      auto& seenMask = seen[classInfo.name];
   186      const auto classMask = getMask(classInfo.type);
   187  
   188      if (classMask & seenMask)
   189      {
   190        status.warn(classInfo.location, "Duplicate class info '" + classInfo.name + "'");
   191      }
   192      else if ((seenMask & baseClassMask) || (seenMask != 0 && (classMask & baseClassMask)))
   193      {
   194        status.warn(classInfo.location, "Redundant class info '" + classInfo.name + "'");
   195      }
   196      else
   197      {
   198        result.push_back(classInfo);
   199        seenMask |= classMask;
   200      }
   201    }
   202  
   203    return result;
   204  }
